{
  "prospect": "Verdeluz Cosméticos Veganos",
  "periodo": "Outubro/2025 a Setembro/2026",
  "secoes": [
    {
      "titulo": "Receita e investimento",
      "graficos": [
        {
          "arquivo": "investimento-total-mensal.png",
          "observacao": "Investimento total de R$ 262 mil no período (Meta mais Google), média de R$ 21,8 mil por mês. Picos em NOV (R$ 28,3 mil) e MAI (R$ 31,5 mil); menor valor em JAN (R$ 13,8 mil); maior valor em SET (R$ 32,9 mil). Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "receita-captada-vs-aprovada.png",
          "observacao": "Receita captada de R$ 1,22 mi e aprovada de R$ 1,14 mi no período. Picos em NOV (R$ 190,3 mil captada e R$ 175,2 mil aprovada) e MAI (R$ 135,3 mil e R$ 126,8 mil). De JAN a ABR a receita captada fica entre R$ 75 mil e R$ 77 mil. A média mensal captada é de R$ 101,7 mil; no kickoff, o faturamento citado foi de cerca de R$ 125 mil por mês. Confirme se esses valores estão corretos e qual número representa o faturamento mensal."
        },
        {
          "arquivo": "taxa-de-quebra.png",
          "observacao": "Taxa de quebra (diferença entre receita captada e aprovada): 4,9% em OUT, pico de 7,9% em NOV, 5,5% em JAN e 7,1% em SET, com média de 6,3%. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "roas-global.png",
          "observacao": "ROAS bruto de 6,5x em OUT, pico de 6,7x em NOV e queda até 3,1x em SET. No período inteiro: 4,7x bruto e 4,4x aprovado. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "roas-por-plataforma.png",
          "observacao": "Google: 3,7x em OUT e 2,0x em SET. Meta: 2,0x em OUT e 0,8x em SET, abaixo de 1x desde JUL. Confirme se esses valores conferem com os painéis do Google Ads e do Meta Ads."
        }
      ]
    },
    {
      "titulo": "Tráfego e conversão",
      "graficos": [
        {
          "arquivo": "sessoes-total-e-por-plataforma.png",
          "observacao": "Total de 442,6 mil sessões no período. Pico em NOV (54,3 mil), segundo maior volume em MAI (41,8 mil) e menor volume em JAN e FEV (30,6 mil). Confirme se esses valores estão corretos, de acordo com o Google Analytics."
        },
        {
          "arquivo": "dependencia-midia-paga.png",
          "observacao": "Participação das sessões pagas no total: média de 44,7%, mínima de 31,0% em ABR e máxima de 54,7% em SET. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "conversao-global.png",
          "observacao": "Taxa de conversão global: pico de 2,05% em NOV, menor valor de 1,00% em ABR e 1,40% em SET, com média de 1,38%. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "conversao-google.png",
          "observacao": "Conversão do Google: 2,20% em OUT e 1,90% em SET, em queda ao longo do período. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "conversao-meta.png",
          "observacao": "Conversão do Meta: 0,90% em OUT e 0,70% em SET, em queda ao longo do período. Confirme se esses valores estão corretos."
        }
      ]
    },
    {
      "titulo": "Vendas e catálogo",
      "graficos": [
        {
          "arquivo": "curva-abc-faturamento.png",
          "observacao": null
        },
        {
          "arquivo": "top-10-produtos-faturamento.png",
          "observacao": "Os três produtos que mais faturam são o sérum de vitamina C (22,0%), o hidratante facial gel-creme (16,0%) e o protetor solar FPS 50 (13,0%). Confirme se esse ranking de produtos está correto."
        },
        {
          "arquivo": "tabela-produtos-curva-abc.png",
          "observacao": "Faturamento do relatório de produtos: R$ 1,17 mi, em 10.928 unidades e 58 produtos. A Curva A reúne 9 produtos e R$ 924,4 mil (78,9%). Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "tabela-produtos-curva-a.png",
          "observacao": null
        }
      ]
    },
    {
      "titulo": "Clientes",
      "graficos": [
        {
          "arquivo": "cac-mensal.png",
          "observacao": "Custo de aquisição por cliente novo (investimento total dividido pelos clientes novos do mês): R$ 49,5 em OUT, menor valor de R$ 40,1 em NOV e maior valor de R$ 112,7 em SET, com média de R$ 71,9. Confirme se esses valores estão corretos."
        },
        {
          "arquivo": "clientes-novos-vs-recorrentes.png",
          "observacao": "Clientes novos: 63,9% das vendas do site em OUT e 58,1% em SET. A base histórica do relatório de clientes tem 10.400 clientes, receita de R$ 3,24 mi, ticket médio de R$ 191,8 por pedido e 1,63 pedido por cliente, e 69% compraram uma única vez. Confirme se esses valores estão corretos."
        }
      ]
    }
  ],
  "limitacoes": null
}
